  "selected_angles": [
    {
      "local_key": "m1-geography-decision",
      "rank": 1,
      "disposition": "SELECT",
      "title": "How we decide where a wedding venue should advertise",
      "central_point": "Choosing where to advertise a venue takes more than listing nearby cities. We look at the current targeting and listen to what the owner has learned about where ideal clients come from and how inquiries from other areas fit; that context informs our recommendation.",
      "why_worthwhile": "This exchange shows WIA’s strategic judgment in context: the venue owner contributes knowledge of her market, and Whitney connects it to the targeting already in place before recommending which areas to include. That is more useful to prospects than a standalone list of cities or a general rule about geographic targeting.",
      "audience": "Wedding venue owners and other wedding professionals deciding which service areas to target in their advertising.",
      "intended_shift": "Understand that a useful targeting recommendation should account for the business’s experience with its clients and inquiries, and trust that WIA brings that knowledge into campaign decisions.",
      "primary_pillar": "WARM",
      "content_type": "process",
      "strategic_rationale": "The purpose is to build trust by showing how WIA combines advertising review with the client’s knowledge of their market. The city choices are the supporting example, not the lesson for every venue.",
      "source_demonstration": "Lauren describes the valley cities as an area that sends some clients, but says she has seen price sensitivity and many inquiries she did not consider highly qualified from a previous campaign there. She identifies other areas as more typical of her ideal client and asks whether to test broadly or focus. Whitney notes that the current Meta targeting is centered on San Luis Obispo and recommends opening it to the Bay Area, Los Angeles, and San Diego while leaving the four valley cities off.",
      "moment_keys": [
        "m1-geography-and-buyer-knowledge"
      ],
      "evidence_refs": [
        "m1.t0285",
        "m1.t0291",
        "m1.t0296",
        "m1.t0299",
        "m1.t0302",
        "m1.t0309",
        "m1.t0312",
        "m1.t0313",
        "m1.t0316"
      ],
      "claims": [
        {
          "claim": "Lauren says the valley cities send some clients, while she has noticed price sensitivity and recalls many inquiries from a previous campaign there that she did not consider highly qualified.",
          "state": "spoken_view",
          "source_refs": [
            "m1.t0291",
            "m1.t0296",
            "m1.t0299"
          ],
          "knowledge_refs": []
        },
        {
          "claim": "Lauren identifies the Bay Area, San Francisco, San Jose, Los Angeles, and Santa Barbara as areas more typical of her ideal client, and asks whether to focus or test more broadly.",
          "state": "spoken_view",
          "source_refs": [
            "m1.t0302",
            "m1.t0309"
          ],
          "knowledge_refs": []
        },
        {
          "claim": "Whitney says the existing Meta targeting is focused on San Luis Obispo and recommends adding the Bay Area, Los Angeles, and San Diego while leaving the four valley cities off.",
          "state": "proposed_action",
          "source_refs": [
            "m1.t0312",
            "m1.t0313",
            "m1.t0316"
          ],
          "knowledge_refs": []
        },
        {
          "claim": "WIA’s approach brings advertising knowledge together with the client’s knowledge of their service, buyers, and market.",
          "state": "brand_perspective",
          "source_refs": [],
          "knowledge_refs": [
            "handbook"
          ]
        }
      ],
      "claim_boundaries": [
        "Lauren’s account is her reported experience, not a quantified comparison or proof that the locations caused lower-quality inquiries.",
        "The recommended locations are specific to this venue and its market. Do not present them as a general targeting prescription.",
        "Keep the client anonymized unless separate authorization for public naming is supplied."
      ],
      "development_direction": "Walk through the decision in order: Lauren’s mixed experience with the valley cities, her description of where ideal clients more often come from, Whitney’s review of the existing targeting, and the resulting recommendation. Make clear that the owner’s local knowledge informed the decision without turning her experience into a universal market rule.",
      "tension": "The valley cities send some clients, but Lauren has also seen more price sensitivity and inquiries she considered less qualified there.",
      "offer_connection": null,
      "possible_format": null,
      "judgments": {
        "audience_relevance": {
          "value": 5,
          "reason": "Service-area targeting is a recognizable decision for venue owners, and the exchange shows why their client knowledge can matter."
        },
        "strategic_value_brand_fit": {
          "value": 5,
          "reason": "It makes WIA’s collaboration and business-specific campaign judgment tangible."
        },
        "distinctiveness": {
          "value": 4,
          "reason": "The specific exchange of owner context, current targeting review, and resulting recommendation gives the broader process point a concrete example."
        },
        "appropriate_depth": {
          "value": 5,
          "reason": "The discussion supports a clear decision sequence without requiring a full geographic-targeting tutorial."
        },
        "voice_framing": {
          "value": 5,
          "reason": "The framing is direct and specific, and centers the venue owner’s expertise alongside WIA’s."
        },
        "source_support": {
          "value": 5,
          "reason": "The owner’s market observations, Whitney’s review, and the specific recommendation appear in the supplied turns."
        }
      },
      "nearest_alternative": {
        "candidate_key": null,
        "central_point": "A venue should include the Bay Area, Los Angeles, and San Diego and leave the four valley cities out of its targeting.",
        "comparison_reason": "This is a considered, unpublished alternative, but it reduces the exchange to a client-specific city list. The selected direction better carries the broader story of how WIA uses the owner’s knowledge and the existing campaign setup to make a recommendation."
      }
    },
    {
      "local_key": "m1-campaign-review",
      "rank": 2,
      "disposition": "SELECT",
      "title": "What we check before recommending a campaign pause",
      "central_point": "A lead-focused Meta campaign showed no leads in the tracking Whitney could see after spending over $500. She connected that observation to its very small audience of recent website visitors and recommended turning it off while new campaigns were being developed. The exchange shows how campaign purpose, visible tracking, and audience size can inform a specific account decision.",
      "why_worthwhile": "The conversation makes a second, distinct part of WIA’s work visible: examining what a campaign is meant to do and what the account shows before recommending a change. That gives prospective clients a concrete example of campaign review without claiming that this recommendation produced a result.",
      "audience": "Wedding venue owners and other wedding professionals who want to understand how an advertising partner evaluates campaigns that are spending without leads appearing in tracking.",
      "intended_shift": "Understand that a recommendation to pause a campaign can come from looking at its objective, visible tracking, and audience size together, rather than treating spend alone as the whole picture.",
      "primary_pillar": "WARM",
      "content_type": "process",
      "strategic_rationale": "This is trust-building process content: Whitney explains the account-specific reasoning behind a recommendation. It is separate from the geographic decision, which concerns where the venue should reach potential clients.",
      "source_demonstration": "Whitney says the existing lead campaign appears to have spent over $500 without leads visible in the tracking. She says it was targeting only people who had visited the website in the previous 45 days, describes that as a very small audience, and recommends turning the campaign off while new campaigns are developed.",
      "moment_keys": [
        "m1-geography-and-buyer-knowledge"
      ],
      "evidence_refs": [
        "m1.t0318",
        "m1.t0320",
        "m1.t0322",
        "m1.t0326",
        "m1.t0328",
        "m1.t0331"
      ],
      "claims": [
        {
          "claim": "Whitney says the lead-focused campaign appeared to have spent over $500 without generating leads in the tracking she could see.",
          "state": "spoken_view",
          "source_refs": [
            "m1.t0318",
            "m1.t0320"
          ],
          "knowledge_refs": []
        },
        {
          "claim": "Whitney says the campaign targeted people who had visited the website in the prior 45 days and describes that audience as very small.",
          "state": "spoken_view",
          "source_refs": [
            "m1.t0320",
            "m1.t0322"
          ],
          "knowledge_refs": []
        },
        {
          "claim": "Whitney recommends turning the campaign off while new campaigns are being developed and says she will proceed with turning it off.",
          "state": "proposed_action",
          "source_refs": [
            "m1.t0326",
            "m1.t0328",
            "m1.t0331"
          ],
          "knowledge_refs": []
        }
      ],
      "claim_boundaries": [
        "Preserve Whitney’s qualification that the no-lead observation was based on the tracking visible to her. The transcript does not independently verify attribution or the final campaign status.",
        "The spend is reported as over $500, with no timeframe supplied. Do not add one or characterize the amount as a measured loss.",
        "The audience-size assessment and pause recommendation are specific to this campaign. Do not imply that retargeting audiences should never be used to generate leads."
      ],
      "development_direction": "Show the sequence from campaign objective, to what Whitney could see in tracking, to the recent-visitor audience and her recommendation. Keep it as an account-specific example; do not turn the 45-day audience observation into a universal platform rule or imply that the later campaign changes had a verified outcome.",
      "tension": "The campaign was intended to generate leads, but Whitney saw no leads in the available tracking while spend had passed $500.",
      "offer_connection": null,
      "possible_format": null,
      "judgments": {
        "audience_relevance": {
          "value": 4,
          "reason": "Owners managing paid campaigns can recognize the concern of spend with no leads visible, though the example is specific to one account."
        },
        "strategic_value_brand_fit": {
          "value": 5,
          "reason": "Whitney explains a concrete account decision, supporting trust in WIA’s advertising judgment."
        },
        "distinctiveness": {
          "value": 4,
          "reason": "The combination of campaign purpose, visible tracking, and audience size gives the example more substance than a generic pause-or-continue lesson."
        },
        "appropriate_depth": {
          "value": 4,
          "reason": "There is enough reasoning to explain the recommendation, provided the development stays bounded to this campaign."
        },
        "voice_framing": {
          "value": 4,
          "reason": "A calm account-review story suits the evidence; preserve the uncertainty around tracking and avoid a dramatic loss framing."
        },
        "source_support": {
          "value": 4,
          "reason": "The observation and recommendation are directly discussed, but the transcript does not independently verify attribution or platform implementation."
        }
      },
      "nearest_alternative": {
        "candidate_key": null,
        "central_point": "A 45-day website-visitor audience may be too small to generate leads.",
        "comparison_reason": "This is a considered, unpublished technical alternative. The selected angle is stronger because it shows Whitney’s account-specific reasoning across campaign purpose, visible tracking, and audience size rather than presenting one audience-size rule."
      }
    }
  ],
